import{_ as i,o as a,h as s,a2 as t}from"./chunks/framework.Ciawx864.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"pages/Troubleshooting.md","filePath":"pages/Troubleshooting.md"}'),o={name:"pages/Troubleshooting.md"};function n(r,e,l,h,d,c){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="ui5-server" tabindex="-1">UI5 Server <a class="header-anchor" href="#ui5-server" aria-label="Permalink to &quot;UI5 Server&quot;">​</a></h2><h3 id="chrome-redirects-http-urls-to-https-err-ssl-protocol-error" tabindex="-1">Chrome Redirects HTTP URLs to HTTPS (<code>ERR_SSL_PROTOCOL_ERROR</code>) <a class="header-anchor" href="#chrome-redirects-http-urls-to-https-err-ssl-protocol-error" aria-label="Permalink to &quot;Chrome Redirects HTTP URLs to HTTPS (`ERR_SSL_PROTOCOL_ERROR`)&quot;">​</a></h3><p>An HTTPS server or proxy that was previously running on a domain (e.g. <code>localhost</code>), might have set an HSTS header, enforcing Chrome to always use HTTPS for this domain. See <a href="https://www.chromium.org/hsts" target="_blank" rel="noreferrer">https://www.chromium.org/hsts</a>. This makes it impossible to connect to an HTTP-only server running on the same domain.</p><h4 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h4><p>You need to delete the HSTS mapping in <a href="chrome://net-internals/#hsts" target="_blank" rel="noreferrer">chrome://net-internals/#hsts</a> by entering the domain name (e.g. <code>localhost</code>) and pressing &quot;delete&quot;.</p><h2 id="issues-not-listed-here" tabindex="-1">Issues Not Listed Here <a class="header-anchor" href="#issues-not-listed-here" aria-label="Permalink to &quot;Issues Not Listed Here&quot;">​</a></h2><p>Please follow our <a href="https://github.com/UI5/cli/blob/main/CONTRIBUTING.md#report-an-issue" target="_blank" rel="noreferrer">Contribution Guidelines</a> on how to report an issue.</p><h2 id="ui5-project" tabindex="-1">UI5 Project <a class="header-anchor" href="#ui5-project" aria-label="Permalink to &quot;UI5 Project&quot;">​</a></h2><h3 id="ui5-taking-too-much-disk-space" tabindex="-1"><code>~/.ui5</code> Taking too Much Disk Space <a class="header-anchor" href="#ui5-taking-too-much-disk-space" aria-label="Permalink to &quot;`~/.ui5` Taking too Much Disk Space&quot;">​</a></h3><p>UI5 CLI stores several kinds of data under your user&#39;s home directory in <code>~/.ui5/</code>:</p><table tabindex="0"><thead><tr><th>Directory</th><th>Contents</th><th>Safe to delete?</th></tr></thead><tbody><tr><td><code>~/.ui5/framework/</code></td><td>Downloaded UI5 framework dependencies (one copy per version)</td><td>Yes — re-downloaded on next invocation</td></tr><tr><td><code>~/.ui5/buildCache/</code></td><td>Build cache used by <code>ui5 build</code> and <code>ui5 serve</code> (see <a href="./Builder#build-cache-control">Build Cache Control</a>)</td><td>Yes — rebuilt on next <code>ui5 build</code> / <code>ui5 serve</code></td></tr><tr><td><code>~/.ui5/server/</code></td><td>Locally generated SSL certificate and private key for HTTPS / HTTP/2 mode</td><td>Yes — regenerated on next HTTPS server start; the new certificate must be re-trusted</td></tr></tbody></table><h4 id="resolution-1" tabindex="-1">Resolution <a class="header-anchor" href="#resolution-1" aria-label="Permalink to &quot;Resolution&quot;">​</a></h4><p>Use the dedicated cache clean command, which removes all cached data:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ui5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cache</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span></span></code></pre></div><p>For a detailed preview and grouped cleanup summary, use the <code>--verbose</code> flag:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ui5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cache</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --verbose</span></span></code></pre></div><p>To skip the confirmation prompt (for example in CI environments), use the <code>--force</code> flag. In non-verbose mode with <code>--force</code>, the command runs completely silent:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ui5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cache</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre></div><p>The command removes the following cached data:</p><ul><li><strong>UI5 Framework packages</strong> — downloaded UI5 library files (<code>~/.ui5/framework/</code>)</li><li><strong>Build cache</strong> — build data (<code>~/.ui5/buildCache/</code>)</li></ul><p>If a previous <code>ui5 cache clean</code> was interrupted (for example, because the process was killed or the system crashed), the command also detects and removes any leftover data from that interrupted operation. This data is listed as separate entries:</p><ul><li><strong>Stale UI5 Framework packages</strong> — incomplete framework directories left over from a previously interrupted cleanup (<code>~/.ui5/_framework_to_delete_*/</code>)</li><li><strong>Stale build cache</strong> — freed database pages not yet reclaimed during a previously interrupted cleanup</li></ul><p>Any required framework dependencies will be re-downloaded during the next UI5 CLI invocation.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If you have configured a custom data directory via <code>UI5_DATA_DIR</code> or <code>ui5 config set ui5DataDir</code>, the <code>ui5 cache clean</code> command will clean up that location instead of the default <code>~/.ui5/</code>. See <a href="#changing-ui5-cli-s-data-directory">Changing UI5 CLI&#39;s Data Directory</a>.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Only remove these directories, or run <code>ui5 cache clean</code>, when no UI5 CLI process and no <code>@ui5/*</code> API consumer is actively running. Running <code>ui5 cache clean</code> while <code>ui5 build</code> or <code>ui5 serve</code> is in progress can break the running process and lead to failed or inconsistent results.</p></div><h2 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h2><h3 id="changing-the-log-level" tabindex="-1">Changing the Log Level <a class="header-anchor" href="#changing-the-log-level" aria-label="Permalink to &quot;Changing the Log Level&quot;">​</a></h3><p>In CI environments or in a combination with other tools, the usage of <a href="https://ui5.github.io/cli/v5/pages/CLI/#common-options" target="_blank" rel="noreferrer">UI5 CLI&#39;s <code>--log-level</code></a> command parameter might be inconvenient and even impossible.</p><h4 id="resolution-2" tabindex="-1">Resolution <a class="header-anchor" href="#resolution-2" aria-label="Permalink to &quot;Resolution&quot;">​</a></h4><p>Replace UI5 CLI&#39;s <code>--log-level</code> option with the <code>UI5_LOG_LVL</code> environment variable.</p><p>Example:</p><p><code>UI5_LOG_LVL=silly ui5 build</code></p><p>On Windows:</p><p><code>set UI5_LOG_LVL=silly ui5 build</code></p><p>Cross Environment via <a href="https://www.npmjs.com/package/cross-env" target="_blank" rel="noreferrer">cross-env</a>:</p><p><code>cross-env UI5_LOG_LVL=silly ui5 build</code></p><p>UI5 + Karma:</p><p><code>cross-env UI5_LOG_LVL=verbose npm run karma</code></p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The combination of the <code>UI5_LOG_LVL</code> environment variable with the <code>--log-level</code> CLI parameter might lead to unexpected results; they should be used interchangeably but not together. The CLI parameter takes precedence over the <code>UI5_LOG_LVL</code> environment variable.</p></div><h3 id="disabling-interactive-ui5-serve-output" tabindex="-1">Disabling Interactive <code>ui5 serve</code> Output <a class="header-anchor" href="#disabling-interactive-ui5-serve-output" aria-label="Permalink to &quot;Disabling Interactive `ui5 serve` Output&quot;">​</a></h3><p>When <code>ui5 serve</code> runs in an interactive terminal, it can render a live status banner instead of plain log output.</p><h4 id="resolution-3" tabindex="-1">Resolution <a class="header-anchor" href="#resolution-3" aria-label="Permalink to &quot;Resolution&quot;">​</a></h4><p>Set the <code>UI5_CLI_NO_INTERACTIVE</code> environment variable to any value to force plain output.</p><p>Unix:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UI5_CLI_NO_INTERACTIVE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ui5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><p>Windows:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> UI5_CLI_NO_INTERACTIVE=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ui5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><p>Cross Environment via <a href="https://www.npmjs.com/package/cross-env" target="_blank" rel="noreferrer">cross-env</a>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cross-env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> UI5_CLI_NO_INTERACTIVE=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ui5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><h3 id="changing-ui5-cli-s-data-directory" tabindex="-1">Changing UI5 CLI&#39;s Data Directory <a class="header-anchor" href="#changing-ui5-cli-s-data-directory" aria-label="Permalink to &quot;Changing UI5 CLI&#39;s Data Directory&quot;">​</a></h3><p>UI5 CLI&#39;s data directory is by default at <code>~/.ui5</code>. It&#39;s the place where the framework artifacts are stored. In some cases and environments this is not a convenient location and the user needs to provide a better one.</p><p>The path to it can either be provided via environment variable or permanently set in the configuration.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Paths are resolved relative to the current root project path (i.e. where the package.json is located).</p></div><h4 id="environment-variable-ui5-data-dir" tabindex="-1">Environment variable <code>UI5_DATA_DIR</code> <a class="header-anchor" href="#environment-variable-ui5-data-dir" aria-label="Permalink to &quot;Environment variable  `UI5_DATA_DIR`&quot;">​</a></h4><p>Unix:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UI5_DATA_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/my/custom/location/.ui5</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ui5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>Windows:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> UI5_DATA_DIR=&quot;C:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">my</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">custom</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">location</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\\\</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.ui5&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ui5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><h4 id="configuration-ui5datadir" tabindex="-1">Configuration <code>ui5DataDir</code> <a class="header-anchor" href="#configuration-ui5datadir" aria-label="Permalink to &quot;Configuration `ui5DataDir`&quot;">​</a></h4><p>Configure a custom directory:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ui5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ui5DataDir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /my/custom/location/.ui5</span></span></code></pre></div><p>Unset the configuration to switch back to the default directory:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ui5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ui5DataDir</span></span></code></pre></div>',64)])])}const k=i(o,[["render",n]]);export{u as __pageData,k as default};
